        "【第 1 步：審題定位 · 題眼與已知】第一部分算熱量：整瓶容量 300 mL，標示基準為「每 100 mL」（即整瓶共 3 倍量），含蛋白質 3.0 g、脂質 2.0 g、醣類 11.0 g，另有礦物質鈉 45 mg、鈣 120 mg。第二部分判試劑：甲（葡萄糖還原糖）、乙（澱粉）、丙（同時含澱粉＋麥芽糖還原糖）、丁（水，無糖無澱粉）。",
        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 Bc-IV-2 養分熱量與檢測：① 熱量公式 ＝（醣類 g × 4 ＋ 蛋白質 g × 4 ＋ 脂質 g × 9）大卡，鈉與鈣屬礦物質，熱量為 0 大卡；② 碘液原色為「黃褐色」，遇澱粉變「藍黑色」；③ 本氏液原色為「淡藍色」，必須經「隔水加熱」後，遇葡萄糖或麥芽糖等還原糖才會依濃度變為綠、黃、橙、紅色。",
