        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：漏乘整瓶倍數 3（只算了 100 mL 的 74 大卡），且將碘液與本氏液的檢測對象顛倒。\n• 選項 (C) 錯誤：熱量計算正確，但本氏液在「常溫尚未隔水加熱前」絕不會變色（仍為淡藍色），這是段考實驗題頭號文字陷阱。\n• 選項 (D) 錯誤：誤將鈉 45 mg 與鈣 120 mg 當成產熱養分乘進算式，且誤判丙與丁的呈色。",
