        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 檢視突變與施藥的時間因果：第一年即測得 1.5% 抗藥菌株，證實隨機突變造成的「個體差異」早在環境篩選前即存在，並非藥物誘導定向突變。\n2. 檢視篩選過程：連續五年投予甲抗生素構成嚴苛環境淘汰壓力，98.5% 不具抗藥性的細菌死亡無法繁殖，而 1.5% 具抗藥性的細菌存活下來並以等比級數分裂繁衍，五年後佔比遂升至 88.0%，完全符合天擇機制，故選 (B)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：標準拉馬克「用進廢退／定向適應」錯誤迷思！突變是隨機且無方向性的，生物絕對無法「為了適應某藥物而主動研發突變出對應基因」。\n• 選項 (C) 錯誤：混淆天擇與人擇！「人擇」是人類依自身需求（如甜玉米、短腿臘腸犬）刻意保留喜愛性狀繁殖；人類施用抗生素本意是想「消滅」細菌而非想培育超級細菌，對細菌而言抗生素是生存環境的致死逆境，屬於「天擇」篩選機制！\n• 選項 (D) 錯誤：突變具隨機性，抗甲抗生素的基因未必能抵抗作用機制不同的乙抗生素（除非族群中恰好又另有極少數對乙具抗藥性突變之個體再經新一輪篩選）。",
