        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 Gc-IV-1 生物命名與分類：\n• 二名法結構：第 1 字為「屬名」（名詞，字首大寫），第 2 字為「種小名」（形容詞，全小寫）；屬名相同即為「同屬」，兩字皆同才為「同種」。\n• 分類七階層「界 ➔ 門 ➔ 綱 ➔ 目 ➔ 科 ➔ 屬 ➔ 種」：若兩生物在較小階層相同（如同屬），則往上推的所有大階層（同科、同目、同綱、同門、同界）必然全部相同！\n• 種子植物二分法：松、杉、柏、銀杏、蘇鐵為「裸子植物」（具毬果與種子，無花無果實）；櫻花為「被子植物」（有花與包覆種子的果實）。",
