        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (B) 錯誤：甲的「taiwanensis」是種小名（形容產於臺灣），丙的「Taiwania」是屬名（臺灣杉屬），兩者既不同屬更不同種，自然狀態下無法雜交產下有生殖能力的後代。\n• 選項 (C) 錯誤：將屬名（前字名詞）與種小名（後字形容詞）順序顛倒；且「同屬必同科、同目」，絕不可能同屬卻不同科！\n• 選項 (D) 錯誤：裸子植物（松、杉）傳播的是「花粉」並結出「種子（有性生殖）」，並非像蕨類靠「孢子」繁殖。",
