        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 Bd-IV-3 與 tr-IV-1 捉放法比例原理：\n假設標記個體在母群體中均勻分布，則「池中標記魚佔全池總魚數的比例」約等於「再捕樣本中標記魚佔樣本總數的比例」：\nM / N ＝ m / n  ➔  移項得核心公式：N ＝ (M × n) ÷ m。",
