        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱岩石循環與地震基本概念（Ia-IV-2、Ia-IV-4）：\n1. 三大岩類成因定錨：岩漿冷卻結晶（作用 ①）→ 火成岩（甲）；沉積物壓密膠結（作用 ②）→ 沉積岩（乙）；固態高溫高壓變質再結晶（作用 ③）→ 變質岩（丙）；高溫熔融（作用 ④）→ 岩漿。\n2. 常見原岩與變質岩對應：頁岩 → 板岩 → 片岩；石灰岩 → 大理岩；石英砂岩 → 石英岩；花崗岩 → 片麻岩。\n3. 震源與震央：地下岩層實際斷裂錯動釋放能量處為「震源（Hypocenter）」，震源垂直投影到地表的點為「震央（Epicenter）」。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 確立代號身分：甲岩類 ＝ 火成岩（作用 ① 為冷卻凝固結晶）；乙岩類 ＝ 沉積岩（作用 ② 為壓密與膠結）；丙岩類 ＝ 變質岩（作用 ③ 為固態高溫高壓變質作用）。\n2. 檢驗臺灣板岩成因：原屬於沉積岩（乙）的泥質「頁岩」，受蓬萊造山運動板塊強烈擠壓，在地下深處經固態高溫高壓【作用 ③】變質為具劈理構造的「板岩」（丙），完全未經過熔融成岩漿。\n3. 對照四個選項，唯有選項 (B) 的岩類配對與變質路徑完全正確。",
