      "title": "【會考經典地質剖面改編】傾斜含水層、受壓水面與四口水井出水狀態判讀",
      "stem": "某盆地邊緣的地下地質剖面由上而下依序分布四層傾斜延伸的岩層（自高海拔山區向低海拔平原傾斜）：\n• 第一層（最上層）：透水砂礫層（自由含水層），其內部測得的「自由地下水面」海拔高度穩定維持在 55 公尺。\n• 第二層：緻密厚實的不透水頁岩層（分布於海拔 35～48 公尺區間，完整隔絕上下水層）。\n• 第三層：夾在第二層與第四層之間的「受壓透水砂岩層（受壓含水層）」；此砂岩層向高山延伸出露地表的補注區長期受雨水補注，其「受壓水面」海拔高度達 85 公尺。\n• 第四層（最底層）：緻密不透水花崗岩基盤與頁岩層。\n今在平原與山坡不同位置鑽設甲、乙、丙、丁四口垂直水井（丙、丁兩井之上段井壁皆以水泥密封管隔絕第一層地下水，僅在井底開孔取水），各井參數如下：\n• 甲井：井口地表海拔 70 公尺，井底開孔於海拔 60 公尺處（位於第一層透水砂礫層內）。\n• 乙井：井口地表海拔 68 公尺，井底開孔於海拔 49 公尺處（位於第一層透水砂礫層內）。\n• 丙井：井口地表海拔 62 公尺，井底穿過第二層頁岩、開孔於海拔 25 公尺處（位於第三層受壓透水砂岩層內）。\n• 丁井：井口地表海拔 60 公尺，井底僅鑽至海拔 40 公尺處便停止並開孔（恰停留在第二層緻密頁岩層中央）。\n根據上述地質與水文條件，關於甲、乙、丙、丁四口水井的出水情形與地下水保育敘述，下列何者正確？",
