      "steps": [
        "【第 1 步：審題定位 · 題眼與已知】鎖定剖面中兩個關鍵基準水面：① 第一層自由含水層的「自由地下水面 ＝ 海拔 55 公尺」；② 第三層受壓含水層的「受壓水面 ＝ 海拔 85 公尺」；以及第二層頁岩為「不透水層」。逐一比對甲、乙、丙、丁四井的「井底開孔岩層」、「井底海拔」與「井口海拔」。",
        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱地下水與自流井原理（Ia-IV-1）：\n1. 取水前提：井底開孔必須位於「透水層（砂礫層／砂岩層）」，且「井底海拔 ＜ 該水層對應的水面高度」才會有水進入井管。\n2. 自流井成立雙要件：① 井底必須鑽入受上下不透水層封閉的「受壓含水層」；② 連通管水壓使井水欲上升至與補注區「受壓水面」同高，故當「井口地表海拔 ＜ 受壓水面海拔」時，地下水便會自動湧出井口！\n3. 超抽地下水危害：地層顆粒間失去地下水支撐水壓而被上方岩土重量壓密實，屬於「不可逆」的永久性地層下陷。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 判定甲井（第一層自由水層）：井底海拔 60 m ＞ 自由地下水面 55 m，井底根本還沒挖到地下水面，故甲井為「乾井」。\n2. 判定乙井（第一層自由水層）：井底海拔 49 m ＜ 自由地下水面 55 m ＜ 井口海拔 68 m，地下水會流入井內並維持在海拔 55 m 高度（距井口尚差 13 m），屬於需加裝抽水機的「普通水井」。\n3. 判定丙井（第三層受壓水層）：井底開孔於受壓透水砂岩層（25 m），該層受壓水面高達 85 m，因「井口海拔 62 m ＜ 受壓水面 85 m」，水壓驅動井水自動噴湧出地面，確為「自流井」！\n4. 判定丁井（第二層不透水層）：井底停留在緻密不透水的頁岩層（40 m）中且上段封管，水分子極難流通，無法有效取水。綜合以上，選項 (A) 每一口井的判讀皆精準無誤。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (B) 錯誤：混淆「井內有水」與「自流井噴水」！乙井的水位只會停在自由地下水面 55 m，低於井口 68 m，絕不會自動湧出地表。\n• 選項 (C) 錯誤：忽略井底岩層性質！丁井雖然井口海拔低（60 m），但井底尚未鑽穿第二層不透水頁岩層，根本沒有連通到第三層受壓砂岩層，不會有受壓水噴出。\n• 選項 (D) 錯誤：嚴重防災迷思！超抽地下水造成的地層壓密下陷，孔隙結構已永久塌陷縮小，即使日後豐水期補注雨水，地層也無法像海綿一樣回彈恢復原高度。",
        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】康軒、翰林、南一三版皆以「U 形連通管原理」解釋受壓地下水與自流井：把受壓砂岩層想像成傾斜水管，補注區水面就是高處水塔液面（85 m），只要水龍頭出口（丙井口 62 m）低於水塔液面就會自動噴水；若在海拔 90 m 高坡鑽入同一受壓層，井內水面仍只到 85 m 而非自流井！"
      ]
