      "badge": "108 課綱 Ia-IV-1 · 泥沙收支平衡實戰",
      "stem": "臺灣西部某條入海河川，由上游山區往出海口方向依序設有三個長期監測站：\n• 甲站：位於中上游新建大型水庫的「蓄水庫區上游入口處」。\n• 乙站：位於水庫大壩正下游 5 公里處的河段，該處設有一座跨河公路大橋，且早年曾有業者在此河段下游側進行河床砂石開採。\n• 丙站：位於該河川出海口旁的沙灘海岸。\n假設數十年來全球海平面（最終侵蝕基準面）維持穩定，且沿岸海浪與沿岸流每年帶走丙站沙灘泥沙的能力固定不變。在水庫完工蓄水及下游採砂的雙重人為干預後，關於甲、乙、丙三站發生的地質作用與地貌變遷，下列推論何者最合理？",
