        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱河流與海岸外營力平衡（Ia-IV-1）：\n1. 暫時侵蝕基準面：水庫水面成為上游河段的「暫時侵蝕基準面」（海平面才是最終侵蝕基準面！）。河水流入寬廣水庫時流速驟降，搬運力減弱，泥沙大量沉積於甲站與庫區。\n2. 下游河床掏刷：越過大壩下洩的河水含沙量極低，加上河道採砂挖深河床使坡度變陡、流速加快，乙站「侵蝕速率 ＞ 沉積速率」，河床不斷下切降低。\n3. 海岸泥沙收支：當「河川入海供沙量 ＜ 海浪沿岸流移出沙量」時，海蝕大於海積，沙灘流失、海岸線向陸地方向後退。",
