        "requiredKnowledge": "回推必備知識：臺灣受亞洲大陸（比熱小，冬冷高壓、夏熱低壓）與太平洋（比熱大）海陸性質差異影響，冬季盛行「東北季風」、夏季盛行「西南季風」。受高聳南北走向中央山脈阻擋：冬季東北季風迎風面的基隆、宜蘭冬雨綿綿，背風面的中南部（臺中、嘉南高屏）進入乾季晴朗少雨；夏季西南季風與午後雷陣雨使全臺各地夏季皆多雨，其中南部「夏雨冬乾」對比最極端！",
