      "steps": [
        "【第 1 步：審題定位 · 題眼與已知】確認地理位置為「北半球近地面」，讀出兩氣壓系統數據：① 系統甲由外往內氣壓遞增（1020 → 1024 → 1028 hPa），為「高氣壓中心（H）」；② 系統乙由外往內氣壓遞減（1004 → 1000 → 996 hPa），為「低氣壓中心（L）」，且乙處等壓線較密集。",
        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱氣壓、風與天氣系統原理（Ib-IV-4）：\n1. 風速強弱看「等壓線疏密」：單位距離氣壓差（氣壓梯度力）越大，風速越強，故等壓線越密集風越強，與氣壓絕對數值大小無關！\n2. 北半球近地面高低壓立體流場（受氣壓梯度力＋科氏力偏右＋地表摩擦力）：\n   • 高氣壓（H）：地面「順時針向外旋出（輻散）」＋ 中心垂直「下沉」增溫 → 晴朗少雲。\n   • 低氣壓（L）：地面「逆時針向內旋入（輻合）」＋ 中心垂直「上升」冷卻 → 陰雨多雲。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 檢驗系統甲（高氣壓 H）：空氣自中心向四周流出，受北半球科氏力向右偏轉，近地面呈「順時針向外旋出」；為補充地面流走的空氣，高空空氣在中心「下沉」，下沉壓縮增溫使相對濕度下降、雲滴消散，故系統甲籠罩區天氣晴朗穩定。\n2. 檢驗系統乙（低氣壓 L）：四周空氣向中心匯聚，受北半球科氏力向右偏轉，近地面呈「逆時針向內旋入」，中心空氣堆積被迫「上升」膨脹冷卻，水氣飽和凝結成雲致雨；且乙處等壓線較密集，風速較甲處強勁。\n3. 綜合核對，選項 (A) 完全正確。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (B) 錯誤：將北半球低氣壓的水平旋轉方向記反！北半球低壓地面氣流是「逆時針」向內旋入（南半球低壓才是順時針旋入）。\n• 選項 (C) 錯誤：典型直覺迷思！誤以為氣壓數字大（1028 ＞ 996）風就大；其實風是因「壓力差」而生，等壓線越密集（系統乙）氣壓梯度越大，風速才越強。\n• 選項 (D) 錯誤：忽略地球自轉「科氏力向右偏轉」！在北半球低壓中心正東方，氣壓梯度力雖指向正西，但風向右偏轉（往西北方吹去），故從東南方吹來，實測主要為「東南風（偏南風）」而非直穿等壓線的正東風。",
        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】康軒、翰林、南一三版同步推薦考場萬用「北半球右手大拇指法則」：伸出右手——大拇指朝「下（代表下沉氣流→晴天＝高壓 H）」，四指彎曲即「順時針（往外撥出）」；大拇指朝「上（代表上升氣流→雨天＝低壓 L）」，四指彎曲即「逆時針（往內抓入）」，考場比一下 3 秒鐘零失誤！"
      ]
