        "甲為基隆、乙為高雄、丙為臺中；丙在 1 月平均氣溫最高（19.7°C）是因為盆地地形將熱量封鎖無法散逸",
        "甲為基隆、乙為臺中、丙為高雄；冬季盛行東北季風時，甲位於迎風面受地形抬升多雨，乙與丙則位於山脈背風面（雨影區）而乾燥少雨",
