      "badge": "校內段考壓軸素養 · 減緩 vs 調適精準判準",
      "stem": "聯合國政府間氣候變化專門委員會（IPCC）與我國《氣候變遷因應法》指出，面對全球暖化與極端天氣頻發，人類社會必須同步採取「氣候變遷減緩（Mitigation）」與「氣候變遷調適（Adaptation）」雙軌策略。某縣市政府與在地社區合作提出以下六項具體行動方案：\n• 【方案甲】：逐步除役老舊燃煤火力發電機組，擴大建置廠房屋頂太陽能光電板與西部外海離岸風力發電場。\n• 【方案乙】：針對沿海地層下陷與易淹水低窪社區，興建大型都會公園地下滯洪池、加高防洪堤防並增設移動式抽水機組。\n• 【方案丙】：推動山坡地生態造林與復育沿岸海草床「藍碳」生態系，利用植物光合作用將大氣中的二氧化碳吸收並固定儲存為自然碳匯。\n• 【方案丁】：農業改良場培育「耐高溫、抗乾旱及耐土壤鹽化」的水稻與果樹新品種，並輔導農民依氣候趨勢調整春耕播種期。\n• 【方案戊】：輔導大型鋼鐵與石化廠導入碳捕捉與封存技術（CCS），並以純電動公車全面汰換市區高排碳柴油公車。\n• 【方案己】：建置極端熱浪高溫戶外勞動預警系統、強化山區豪雨土石流潛勢溪流保全戶疏散演練，並擴大登革熱病媒蚊北擴監測網。\n若依課綱與國際氣候行動定義，將上述六項方案精準區分為「減緩」與「調適」兩大類，下列分類結果何者完全正確？",
