        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱動物恆定與排泄判準（Db-IV-3、Dc-IV-4）：\n1. 含氮廢物毒性與水溶性：「氨 ＞ 尿素 ＞ 尿酸」（排泄耗水量亦為氨最多、尿酸最少）。\n2. 呼吸構造三大共同特徵：表面濕潤（利於 O₂ 與 CO₂ 溶解擴散）、表面積大（皺摺／分支／絲狀／泡狀）、壁薄且多布滿微血管（昆蟲氣管系則直接分支送達細胞）。\n3. 排泄定義：排除「體細胞新陳代謝所產生的廢物（CO₂、多餘水分、無機鹽、含氮廢物）」，未進入細胞代謝的食物殘渣由肛門排出稱為「排遺」。",
