        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱地質事件先後判定法則（Hb-IV-1）：\n1. 疊置定律：未倒轉沉積岩層由下而上依序沉積，故「下老上新」。\n2. 截切定律：斷層切穿某岩層，則斷層晚於該岩層；火成岩脈貫穿並烘烤圍岩，則岩脈晚於所有被貫穿烘烤的岩層與構造。\n3. 不整合／侵蝕面法則：構造頂部被侵蝕面削平且未穿過侵蝕面，代表構造發生在侵蝕作用之前，而侵蝕面上方水平岩層則在侵蝕面形成後再度下沉沉積。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 最早期沉積與變形：底部未倒轉沉積岩由下而上依序為頁岩甲 ➔ 砂岩乙 ➔ 石灰岩丙；接著受板塊擠壓發生波狀褶皺，並被逆斷層 X 切穿錯移（故 X 晚於甲、乙、丙）。\n2. 抬升侵蝕與再沉積：甲、乙、丙與逆斷層 X 頂端皆被平坦侵蝕面 Y 削平，且 X 未穿過 Y，證明逆斷層 X 發生在侵蝕面 Y 之前；隨後地殼下沉，於 Y 之上水平沉積礫岩層丁（故 X ➔ Y ➔ 丁）。\n3. 最新岩漿活動：火成岩脈 Z 貫穿甲、乙、丙、X、Y 及最上方的丁直達地表，使丁也出現烘烤變質，且 Z 未被 X 錯開，證明 Z 是全區最晚發生的事件。\n4. 完整排序：沉積甲乙丙 ➔ 褶皺與逆斷層 X 錯移 ➔ 形成侵蝕面 Y ➔ 沉積礫岩層丁 ➔ 火成岩脈 Z 侵入，完全吻合選項 (C)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：若火成岩脈 Z 在逆斷層 X 與沉積丁之前就侵入，則 Z 必然會被逆斷層 X 錯開、被侵蝕面 Y 削平，且不可能貫穿並烘烤尚未沉積的礫岩層丁。\n• 選項 (B) 錯誤：若逆斷層 X 發生在礫岩層丁沉積之後，則斷層 X 應一併切穿侵蝕面 Y 與礫岩層丁，與題幹「X 未穿過 Y 且丁呈水平未變形」矛盾。\n• 選項 (D) 錯誤：違反疊置定律「下老上新」，誤將位於最頂部的水平礫岩層丁當成最古老岩層。",
        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】康軒、翰林、南一三版皆將「烘烤變質帶（接觸變質）」與「斷層終止於侵蝕面」列為地層推理雙鑰匙。逆向檢核口訣：「誰切誰，切者新；誰烤誰，烤者新；誰壓誰，壓者新」，三秒鎖定 Z 最新、甲最老，零失誤破題！"
