        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱颱風成因與天氣災害（Ib-IV-5）：\n1. 北半球低壓環流：受氣壓梯度力、科氏力與地面摩擦力共同作用，北半球颱風地面空氣呈「逆時針向中心旋入」並強烈上升。\n2. 地形效應：迎風坡水氣受中央山脈阻擋抬升凝結致超大豪雨；背風坡空氣越山後絕熱壓縮沉降增溫（每下降 1 km 升溫約 10°C）且相對濕度驟降，形成乾熱「焚風」。\n3. 颱風眼與能量：眼牆上升最劇烈風雨最強，眼中心為微弱「下沉氣流」無風無雨，但中心「氣壓最低」；颱風主能量來自溫暖洋面（＞26°C）水氣凝結釋放的「潛熱」，登陸後水氣斷絕加地形摩擦必迅速減弱。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 繪製環流判讀風向：以花蓮東方海面為圓心畫逆時針旋入箭頭，臺灣北部（宜蘭、臺北）吹強勁偏北／東北至西北風，直衝雪山與中央山脈迎風坡帶來劇烈豪雨；臺灣中南部吹偏西／西北風，氣流翻越高聳中央山脈後在東南部「臺東」背風側下沉增溫，極易引發焚風。\n2. 判讀颱風眼通過花蓮：眼區微弱下沉氣流使雲消雨散、風速驟降，但此處正是低氣壓最核心，地面氣壓降至全過程最低點（待眼牆後側移入，風雨將轉反方向再度狂襲），完全吻合選項 (A)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (B) 錯誤：「順時針向外旋出」是北半球「高氣壓」特徵！北半球颱風（低氣壓）必為逆時針向內旋入，此時西南部吹偏北轉西北／西南風而非東南風。\n• 選項 (C) 錯誤：雙重觀念顛倒！颱風眼中心是「微弱下沉氣流（無風無雨）」，眼牆才是強烈上升氣流（狂風暴雨）；且眼中心氣壓是「最低值」而非最高值。\n• 選項 (D) 錯誤：颱風仰賴溫暖海水蒸發之水氣凝結潛熱維生，一旦登陸臺灣，失去海洋水氣供應且遭中央山脈劇烈摩擦破壞環流，強度必大幅「減弱」而非增強。",
