        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱潮汐變化規律（Ic-IV-4）：\n1. 潮差定義：相鄰滿潮水位與乾潮水位之高度差，即「潮差 ＝ 滿潮潮高 − 乾潮潮高」（注意負號運算！）。\n2. 潮間帶活動安全準則：應選在「退潮末期至乾潮前後」水位最低、沙洲大面積露出時進行，並在開始快速漲潮前返回岸上。\n3. 潮汐每日延遲：相鄰兩次滿潮間隔約 12 小時 25 分（表中 04:20 至 16:45 恰為 12 小時 25 分！），隔天同一次滿潮（經歷兩次潮汐週期）平均延後約 50 分鐘。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 計算上午潮差：第一次滿潮（＋185 cm）減去第一次乾潮（−165 cm）＝ 185 − (−165) ＝ 185 ＋ 165 ＝ 350 cm（3.5 公尺），且農曆十五望日屬「大潮」。\n2. 評估觀察時段：第一次乾潮在 10:32，故 09:30～10:30 正值退潮接近乾潮底點，潮間帶裸露最廣且尚無海水急速回漲危險，最為理想。\n3. 推算隔天第一次滿潮時刻：當日第一次滿潮為 04:20，加上每日平均延遲約 50 分鐘（或由當日第二次滿潮 16:45 再加 12 小時 25 分），得 04:20 ＋ 00:50 ＝ 05:10 前後，完全吻合選項 (B)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：算潮差時忽略負號直接拿絕對值相減（185 − 165 ＝ 20 cm），且誤將農曆十五大潮說成小潮。\n• 選項 (C) 錯誤：15:30～16:45 正處於「漲潮末期至第二次滿潮最高水位（＋180 cm）」，整片潮間帶全被海水淹沒，冒然下海極易溺水受困。\n• 選項 (D) 錯誤：將每日潮汐「延後（遲到）約 50 分鐘」記反成「提早 50 分鐘」。",
