        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 計算甲、丙兩站距離震源／震央距離 d：\n   • 甲站 P 波行進時間 ＝ 13:00:07.0 − 13:00:00 ＝ 7.0 秒 ➔ d甲 ＝ 6.0 km/s × 7.0 s ＝ 42 km（驗算 S 波：42 ÷ 3.5 ＝ 12.0 s，12 − 7 ＝ 5.0 s 完全吻合！）。\n   • 丙站 P 波行進時間 ＝ 13:00:28.0 − 13:00:00 ＝ 28.0 秒 ➔ d丙 ＝ 6.0 km/s × 28.0 s ＝ 168 km（驗算 S 波：168 ÷ 3.5 ＝ 48.0 s，48 − 28 ＝ 20.0 s 完全吻合！同理乙站 d乙 ＝ 6.0 × 16.8 ＝ 100.8 km）。故距離由近到遠為：甲（42 km）＜ 乙（100.8 km）＜ 丙（168 km）。\n2. 計算各站對 S 波的預警時間（S 波抵達時刻 − 警報送達時刻 13:00:13.0）：\n   • 甲站：S 波於 13:00:12.0 已抵達，比 13:00:13.0 的警報還早 1 秒到達（先劇烈搖晃才響警報），落入「預警盲區」！\n   • 丙站：S 波於 13:00:48.0 才抵達，13:00:48.0 − 13:00:13.0 ＝ 35.0 秒（乙站則有 28.8 − 13.0 ＝ 15.8 秒預警時間），完全吻合選項 (B)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：將 Δt 與距離正比關係弄反！就像賽跑快慢兩人同時起跑，跑道越長兩人抵達終點的秒差越大，故 Δt 最小（5 秒）的甲站離震央最近，丙站（168 km）最遠。\n• 選項 (C) 錯誤：嚴重物理數量級錯誤！電磁波速率約 300,000 km/s，而 P 波速率僅約 6 km/s，是「電磁波遠快於地震波」才能搶先預警。\n• 選項 (D) 錯誤：P 波波速較快先抵達（先上下顛簸），S 波波速較慢後抵達（後水平劇烈搖晃），先後順序顛倒。",
