      "stem": "天文社團整理某年度兩場重大天象觀測指南：\n【天象一：6 月 21 日（農曆五月初一）日環食】當天下午臺灣嘉義、花蓮一帶狹長地帶可見太陽中心被遮蔽、周圍留下一圈耀眼金環的「金邊日食」，臺北與高雄則僅見太陽缺一角的日偏食。\n【天象二：5 月 26 日（翌年農曆四月十五）月全食】當天晚間臺灣全島只要天氣晴朗，皆可全程目睹滿月逐漸缺角，完全進入地球本影時並未完全黑暗消失，而是呈現暗紅古銅色的「紅月亮（血月）」。\n根據日、地、月相對運動與光學陰影幾何原理，下列關於日食與月食的比較敘述，何者完全正確？",
